  case elapsed = "elapsed"
  case remaining = "remaining"
}

/// `countdown`'s own props.
public struct CountdownProps: Equatable, Sendable {
  /// Target, ms after the receipt of the state being applied when this prop was set (negative = passed). null shows nothing.
  public var toMs: Double? = nil
  /// README: Countdown formats.
  public var format: CountdownFormat = .countdown

  public init() {}

  /// Applies one prop. `.null` resets it to its default; an invalid value also
  /// resets it and returns `.invalid`; a name this struct doesn't own returns `.unknown`.
  public mutating func set(_ name: String, _ value: PropValue) -> PropSetResult {
    switch name {
    case "toMs":
      if value == .null { toMs = nil; return .ok }
      guard let v = PropDecode.number(value) else { toMs = nil; return .invalid }
      toMs = v
      return .ok
    case "format":
      if value == .null { format = .countdown; return .ok }
      guard let v = PropDecode.string(value).flatMap(CountdownFormat.init(rawValue:)) else { format = .countdown; return .invalid }
      format = v
      return .ok
    default:
      return .unknown
    }
  }
}

/// `format`: HH:mm | HH:mm:ss | h:mm
public enum ClockFormat: String, CaseIterable, Sendable {
  case hourMinute24 = "HH:mm"
  case hourMinuteSecond24 = "HH:mm:ss"
  case hourMinute12 = "h:mm"
}

/// `clock`'s own props.
public struct ClockProps: Equatable, Sendable {
  public var format: ClockFormat = .hourMinute24

  public init() {}

  /// Applies one prop. `.null` resets it to its default; an invalid value also
  /// resets it and returns `.invalid`; a name this struct doesn't own returns `.unknown`.
  public mutating func set(_ name: String, _ value: PropValue) -> PropSetResult {
    switch name {
    case "format":
      if value == .null { format = .hourMinute24; return .ok }
      guard let v = PropDecode.string(value).flatMap(ClockFormat.init(rawValue:)) else { format = .hourMinute24; return .invalid }
      format = v
      return .ok
    default:
      return .unknown
    }
  }
}

/// `pattern`: notification | directionUp | directionDown | success | failure | retry | start | stop | click
public enum HapticPattern: String, CaseIterable, Sendable {
  case notification = "notification"
  case directionUp = "directionUp"
  case directionDown = "directionDown"
  case success = "success"
  case failure = "failure"
  case retry = "retry"
  case start = "start"
  case stop = "stop"
  case click = "click"
}

/// `haptic`'s own props.
public struct HapticProps: Equatable, Sendable {
  /// watchOS WKHapticType names.
  public var pattern: HapticPattern = .click
  public var trigger: PropValue = .null

  public init() {}

  /// Applies one prop. `.null` resets it to its default; an invalid value also
  /// resets it and returns `.invalid`; a name this struct doesn't own returns `.unknown`.
  public mutating func set(_ name: String, _ value: PropValue) -> PropSetResult {
    switch name {
    case "pattern":
      if value == .null { pattern = .click; return .ok }
      guard let v = PropDecode.string(value).flatMap(HapticPattern.init(rawValue:)) else { pattern = .click; return .invalid }
      pattern = v
      return .ok
    case "trigger":
      if value == .null { trigger = .null; return .ok }
      guard let v = Optional(value) else { trigger = .null; return .invalid }
      trigger = v
      return .ok
    default:
      return .unknown
    }
  }
}

